\label{Defn 1}
\begin{enumerate}
\item
A holomorphic function
\(
\mathbf{x}=(x_1,\ldots,x_7):
\mathbb D\longrightarrow
\Gamma_{E(3;3;1,1,1)}
\)
is called a
\textit{$\Gamma_{E(3;3;1,1,1)}$-inner function} if its radial limit
\begin{equation}\label{Gamma_{E(3;3;1,1,1)}-inner function}
\lim_{r\to1^-}\mathbf{x}(rz)
\end{equation}
belongs to $K$ for almost every $z\in\mathbb T$ with respect to
Lebesgue measure.

\item
A holomorphic function
\(
\widetilde{\mathbf{x}}
=
(x_1,x_2,x_3,y_1,y_2):
\mathbb D\longrightarrow
\Gamma_{E(3;2;1,2)}
\)
is called a
\textit{$\Gamma_{E(3;2;1,2)}$-inner function} if its radial limit
\begin{equation}\label{Gamma_{E(3;2;1,2)}-inner function}
\lim_{r\to1^-}\widetilde{\mathbf{x}}(rz)
\end{equation}
belongs to $K_1$ for almost every $z\in\mathbb T$ with respect to
Lebesgue measure.
\end{enumerate}

\label{Prop K}
	Let $\mathbf{x}=(x_1,\ldots,x_7)\in\mathbb{C}^7$. Then the following
	conditions are equivalent:
	\begin{enumerate}
		\item $\mathbf{x}\in K$;
		\item $\mathbf{x}\in\Gamma_{E(3;3;1,1,1)}$ and $|x_7|=1$.
	\end{enumerate}

\label{Prop K_1}
	Let
	\(
	\widetilde{\mathbf{x}}
	=(x_1,x_2,x_3,y_1,y_2)\in\mathbb{C}^5.
	\)
	Then the following conditions are equivalent:
	\begin{enumerate}
		\item $\widetilde{\mathbf{x}}\in K_1$;
		\item $\widetilde{\mathbf{x}}\in\Gamma_{E(3;2;1,2)}$ and
		$|x_3|=1$.
	\end{enumerate}

\label{Interpolation 1}
Let
\(
h=(x_1,\ldots,x_7):\mathbb D\longrightarrow
G_{E(3;3,1,1,1)}
\)
be holomorphic, and let
\[
h(z_j)
=
(x_{1,j},x_{2,j},x_{3,j},x_{4,j},x_{5,j},x_{6,j},x_{7,j}),
\quad 1\leq j\leq N,
\]
where $z_1,\ldots,z_N$ are distinct points in $\mathbb D$.
For fixed $a,b\in\mathbb D$, define
\[
\Psi_{a,b}^{(1)}(\mathbf{x})
=
\frac{
x_1-a x_2-bx_5+abx_7
}{
1-a x_3-bx_4+abx_6
}.
\]
Then
\(
\Psi_{a,b}^{(1)}\circ h:\mathbb D\longrightarrow\mathbb D.
\)
Consequently, for every $a,b\in\mathbb D$,
\[
\left(
\frac{
1-\overline{\Psi_{a,b}^{(1)}(h(z_j))}
\Psi_{a,b}^{(1)}(h(z_i))
}{
1-\overline{z_j}z_i
}
\right)_{i,j=1}^{N}
\geq 0.
\]
Similarly, if
\[
\Psi_{a,b}^{(2)}(\mathbf{x})
=
\frac{
x_2-a x_1-bx_6+abx_7
}{
1-a x_3-bx_4+abx_5
}\quad \text{
and}\quad
\Psi_{a,b}^{(3)}(\mathbf{x})
=
\frac{
x_4-a x_5-bx_2+abx_7
}{
1-a x_1-bx_3+abx_6
},
\]
then
\(
\Psi_{a,b}^{(2)}\circ h,\,
\Psi_{a,b}^{(3)}\circ h
\in H^\infty(\mathbb D),
\)
with norm at most one, and the corresponding Pick matrices are
positive semidefinite.
